      {
        property: "og:description",
        content: "Terms of sale, shipping, returns, warranty and privacy for Pickrel Brothers customers.",
      },
    ],
  }),
  component: PoliciesPage,
});

function PoliciesPage() {
  return (
    <div className="container-page py-10">
      <h1 className="font-display text-3xl font-bold uppercase text-navy">Policies</h1>
      <p className="mt-2 max-w-3xl text-muted-foreground">
